L000201	\section{Variational states and energies: second-quantized approach}
L000202	
L000203	In this supplemental section we provide further details on the variational states used for the monatomic and paired Wigner crystals (WCs), including certain useful operator identities for the $d^\dag$ and $b^\dag$ operators introduced in the main text, as well as more detailed calculations of the variational energies.
L000204	
L000205	\subsection{Variational states and operator identities}
L000206	
L000207	For reference, we record here the Hamiltonian given in Eq.~(1) of the main text:
L000208	    \be
L000209	    H = \sum_{\bfk\sigma} \frac{\hbar^2k^2}{2m^*}c^\dag_{\bfk\sigma}c_{\bfk\sigma} +\frac{1}{2A}\sum_{\bfq \neq 0} v_\bfq \sum_{\substack{\bfk\bfk' \\ \sigma \sigma'}}
L000210	    F_{\bfk+\bfq,\bfk}F_{\bfk'-\bfq,\bfk'}c^\dag_{\bfk+\bfq\sigma}c^\dag_{\bfk'-\bfq\sigma'}c_{\bfk'\sigma'}c_{\bfk\sigma},
L000211	    \label{eq:H}
L000212	    \ee
L000213	where $v_\bfq = 2\pi e^2/q$ is the Fourier transform of the Coulomb interaction, $A$ is the area of the system, and the form factors are
L000214	    \be
L000215	    F_{\bfk, \bfk'}= e^{-i\frac{\Omega}{2}\bfk \times \bfk'}e^{-\frac{\Omega}{4}|\bfk - \bfk'|^2}.
L000216	    \label{eq:form_factor}
L000217	    \ee
L000218	
L000219	For the ordinary, monatomic $N$-electron WC we use the variational state
L000220		\be
L000221		| \Psi \rangle = C d^\dag_{\sigma_1}(\bfR_1) \ldots d^\dag_{\sigma_N}(\bfR_N) | 0 \rangle, \quad d^\dag_\sigma(\bfR_n) = \frac{1}{\sqrt A} \sum_\bfk e^{-i\bfk \cdot \bfR_n} \tilde \Phi(\bfk) c^\dag_{\bfk \sigma},
L000222		\label{eq:wc_anstaz_rspace}
L000223		\ee
L000224	where $\tilde\Phi(\bfk)$ is the Fourier transform of the localized orbital $\Phi(\bfr) = \exp(-r^2/4\sigma^2)/\sqrt{2\pi\sigma^2}$. This type of state was used to describe monatomic WCs in Refs.~\cite{vandijk1991,moulopoulos1993,bonev2008}.
L000225	Operators $d^\dag_\sigma(\bfR_n)$ have the interpretation of creating an electron at WC lattice site $\bfR_n$ with spin $\sigma_n$. The anticommutation relations are
L000226		\be
L000227		\{d_{\sigma}(\bfR),d^\dag_{\sigma'}(\bfR')\} = \delta_{\sigma\sigma'} S(\bfR - \bfR'), \quad \{d_{\sigma}(\bfR),d_{\sigma'}(\bfR')\} = \{d^\dag_{\sigma}(\bfR),d^\dag_{\sigma'}(\bfR')\} = 0.
L000228		\ee
L000229	Function $S$ measures overlaps between localized orbitals:
L000230	    \be
L000231	    S(\bfR - \bfR') = \int \dd^2\bfr ~ \Phi^*(\bfr - \bfR) \Phi(\bfr - \bfR') = e^{-(\bfR - \bfR')^2/8\sigma^2}.
L000232	    \ee
L000233	Throughout we will neglect this exponentially small wave function overlaps between different sites and make the approximation $S(\bfR - \bfR') \approx \delta_{\bfR \bfR'}$, so that the $d^\dag$ operators obey standard fermion anticommutation relations. In this approximation, the normalization constant $C \approx 1$. Higher-order terms in a systematic expansion in powers of $S$ can be found in Refs.~\cite{moulopoulos1993, vandijk1991,bonev2008}. Below we will also make use of the anticommutation relation
L000234		\be
L000235		\{ c_{\bfk\sigma}, d^\dag_{\sigma'}(\bfR_n) \} = \frac{1}{\sqrt A} \delta_{\sigma\sigma'} e^{-i\bfk \cdot \bfR_n} \tilde \Phi(\bfk).
L000236		\ee
L000237	For the paired WC we use the state
L000238		\be
L000239		|\Psi_p \rangle = C_p b^\dag(\bfR_1) b^\dag(\bfR_2) \ldots b^\dag(\bfR_{N_p})| 0 \rangle,
L000240	    \quad b^\dag(\bfR_n) = \frac 1A \sum_{\bfk\bfq \sigma\sigma'} e^{-i\bfq \cdot \bfR_n} \tilde \Phi(\bfq) \tilde \varphi(\bfk)  \chi_{\sigma \sigma'} c^\dag_{\bfq/2+\bfk, \sigma} c^\dag_{\bfq/2-\bfk, \sigma'},
L000241	    \label{eq:paired_ansatz}
L000242		\ee
L000243	where $N_p = N/2$ is the number of pairs.
L000244	The spatial part of the pair wave function localized at site $\bfR_n$ is
L000245	    \be
L000246	    \psi_n(\bfr, \bfr') = \Phi\left(\frac{\bfr + \bfr'}{2} - \bfR_n\right) \varphi(\bfr - \bfr'),
L000247	    \ee
L000248	where $\bfr$ and $\bfr'$ are the coordinates of the two electrons comprising the pair. Functions $\Phi$ and $\varphi$ are the center-of-mass (COM) and relative wave functions, respectively. The spin part of the wave function is $\chi_{\sigma\sigma'}$. For singlet pairing $\chi_{\sigma\sigma'} = (\delta_{\sigma\uparrow}\delta_{\sigma'\downarrow}-\delta_{\sigma\downarrow}\delta_{\sigma'\uparrow})/\sqrt 2$, while for triplet pairing the three possible spin states are $\chi^{(+1)}_{\sigma\sigma'} = \delta_{\sigma\uparrow}\delta_{\sigma'\uparrow}$, $\chi^{(0)}_{\sigma\sigma'} = (\delta_{\sigma\uparrow}\delta_{\sigma'\downarrow}+\delta_{\sigma\downarrow}\delta_{\sigma'\uparrow})/\sqrt 2$, and $\chi^{(-1)}_{\sigma\sigma'} = \delta_{\sigma\downarrow}\delta_{\sigma'\downarrow}$. The state \eqref{eq:paired_ansatz} was used earlier in Ref.~\cite{moulopoulos1993} to describe spin-singlet paired WCs in the three-dimensional electron gas.
L000249	
L000250	Below will make use of the following identities involving the $b^\dag$ operators:
L000251	    \begin{align}
L000252	    [c^\dag_{\bfk\sigma}c_{\bfk'\sigma'}, b^\dag(\bfR_n) ] &= \frac 2A \sum_{\bfk''\sigma''}e^{-i(\bfk' + \bfk'')\cdot \bfR_n} \tilde\Phi(\bfk' + \bfk'') \tilde\varphi\left(\frac{\bfk' - \bfk''}{2}\right) \chi_{\sigma' \sigma''} c^\dag_{\bfk\sigma} c^\dag_{\bfk''\sigma''}, \\
L000253		[b(\bfR_n), [c^\dag_{\bfk\sigma}c_{\bfk'\sigma'}, b^\dag(\bfR_n) ] ] |0 \rangle &= \frac{4}{A^2} \sum_{\bfk''\sigma''} e^{i(\bfk-\bfk')\cdot \bfR_n} \tilde \Phi^*(\bfk + \bfk'')\tilde \Phi(\bfk' + \bfk'') \tilde\varphi^*\left(\frac{\bfk - \bfk''}{2}\right) \tilde\varphi\left(\frac{\bfk' - \bfk''}{2}\right)  \chi_{\sigma \sigma''}\chi_{\sigma' \sigma''} | 0 \rangle,
L000254		\label{eq:nested_comm}
L000255	    \end{align}
L000256	as well as the approximation relations
L000257	    \begin{align}
L000258	    [b(\bfR_n),b^\dag(\bfR_m)] &\approx 0 \quad (m\neq n),
L000259	    \label{eq:b_comm}\\
L000260	    b(\bfR_n)b^\dag(\bfR_n)|0 \rangle &\approx 2 |0\rangle,
L000261	    \label{eq:b_norm}
L000262	    \end{align}
L000263	which are valid in the limit of vanishing intercell overlaps. In this approximation, the constant $C_p \approx 2^{-N_p/2}$.
L000264	
L000265	In the following subsections, we compute expectation values of the Hamiltonian \eqref{eq:H} using the states \eqref{eq:wc_anstaz_rspace} and  \eqref{eq:paired_ansatz}. As described above, we neglect the exponentially small overlaps of wave functions in different unit cells, which gives corrections of the order $\sim \exp(-\alpha a_\text{WC}^2/\sigma^2)$, where $\sigma$ is the width of the localized orbital, $a_\text{WC}$ is the WC lattice constant ,  and $\alpha = \mathcal O(1)$. In the next section of this supplement, we demonstrate that this approximation is equivalent to the ``Hartree approximation" in a first-quantized, wave function language. At various stages of the calculations below, we will make use of the usual passage from discrete to continuous momenta $A^{-1}\sum_\bfk \to \int \dd^2\bfk /(2\pi)^2$.
L000266	
L000267	\subsection{Variational energy of the monatomic WC}
L000268	
L000269	We start with the monatomic WC and adopt the shorthand notation $d^\dag(\bfR_n) \to d^\dag_n$. In the approximation of neglected intercell overlaps, the energy of the monatomic WC is independent of the spin configuration and we will therefore suppress the spin labels in what follows.
L000270	The expectation value of the kinetic energy is	$ \langle \Psi | T | \Psi \rangle = \sum_\bfk \epsilon_\bfk \langle \Psi |  c^\dag_\bfk c_\bfk | \Psi \rangle $. Expanding the expectation value
L000271		\begin{align}
L000272		\langle \Psi |  c^\dag_\bfk c_\bfk | \Psi \rangle &= \langle 0 | d_N \ldots d_1 c^\dag_\bfk c_\bfk d^\dag_1 \ldots d^\dag_N | 0\rangle \\
L000273		&= \sum_i (-1)^{i+1} \{ c_\bfk, d^\dag_i \} \langle 0 | \prod_m d_m c^\dag_\bfk \prod_{n\neq i} d^\dag_n | 0 \rangle \\
L000274		&= \sum_{ij} (-1)^{i+j} \{ c_\bfk, d^\dag_i \} \{d_j, c^\dag_\bfk \}  \langle 0 | \prod_{m\neq j} d_m  \prod_{n\neq i} d^\dag_n | 0 \rangle \\
L000275		&\approx \sum_i \{ c_\bfk, d^\dag_i \} \{d_i,  c^\dag_\bfk \} \\
L000276		&= \frac{N}{A} \tilde \Phi^*(\bfk) \tilde \Phi(\bfk)
L000277		\end{align}
L000278	The second to last line is obtained using the approximation of neglected overlaps \eqref{eq:b_comm}. We thus find
L000279	    \be
L000280	    \langle \Psi | T | \Psi \rangle = N \int \frac{\dd^2\bfk}{(2\pi)^2} ~  \epsilon_\bfk \tilde \Phi^*(\bfk) \tilde\Phi(\bfk) = N\frac{\hbar^2}{4m^*\sigma^2}.
L000281	    \label{eq:t_wc}
L000282	    \ee
L000283	The potential energy is obtained similarly. We have
L000284		\be
L000285		 \langle \Psi | V | \Psi \rangle  = \frac{1}{2A}  \sum_{\bfq \neq 0} v_\bfq \sum_{\bfk \bfk'} F_{\bfk+\bfq, \bfk} F_{\bfk'-\bfq, \bfk'}  \langle \Psi | c^\dag_{\bfk+\bfq}c^\dag_{\bfk'-\bfq} c_{\bfk'} c_{\bfk} | \Psi \rangle.
L000286		\ee
L000287	Neglecting intercell overlaps, one obtains
L000288		\be
L000289		 \langle \Psi | c^\dag_{\bfk+\bfq}c^\dag_{\bfk'-\bfq} c_{\bfk'} c_{\bfk} | \Psi \rangle = \frac{1}{A^2}\sum_{i \neq j} e^{i\bfq \cdot (\bfR_i - \bfR_j)} \tilde \Phi^*(\bfk + \bfq) \tilde \Phi^*(\bfk' - \bfq) \tilde \Phi(\bfk') \tilde \Phi(\bfk) .
L000290		 \ee
L000291	The manipulations required to arrive at this result are similar to those made in calculating the kinetic energy,  with additional oscillatory terms of the form
L000292		\be
L000293		\int \frac{\dd^2\bfk}{(2\pi)^2} ~ F_{\bfk+\bfq, \bfk}\tilde \Phi^*(\bfk+\bfq) \tilde \Phi(\bfk) e^{-i\bfk \cdot (\bfR - \bfR')} \sim e^{-(\bfR - \bfR')^2/8\sigma^2} ,
L000294		\ee
L000295	which are again exponentially small in proportion to the overlap and are thus dropped. We obtain
L000296		 \be
L000297		 \langle \Psi | V | \Psi \rangle = \frac{1}{2A} \sum_{i \neq j } \sum_{\bfq \neq 0 }   v_\bfq e^{i\bfq \cdot (\bfR_i - \bfR_j)}  \left| \int \frac{\dd^2\bfk}{(2\pi)^2} ~ F_{\bfk - \bfq,\bfk} \tilde \Phi^*(\bfk-\bfq) \tilde \Phi(\bfk) \right|^2.
L000298		\ee
L000299	Defining the electron density $n(\bfq)=  \langle \Psi | \sum_\bfk F_{\bfk-\bfq,\bfk} c^\dag_{\bfk-\bfq} c_\bfk | \Psi \rangle$, we have, in the approximation of vanishing overlaps,
L000300		\be
L000301		n(\bfq) =  \sum_j e^{-i \bfq \cdot \bfR_j} n_0(\bfq), \quad n_0(\bfq) \equiv \int \frac{\dd^2\bfk}{(2\pi)^2}~  F_{\bfk - \bfq,\bfk} \tilde \Phi^*(\bfk-\bfq) \tilde \Phi(\bfk) =  e^{-\frac{\sigma^2}{2}\left(1 + \frac{\Omega}{4\sigma^2}\right)^2 q^2}.
L000302		\label{eq:bc_density}
L000303		\ee
L000304	 The potential energy term can then be written
L000305		\be
L000306		\langle \Psi | V | \Psi \rangle = \frac{N}{2A} \sum_{\bfR_n\neq 0} \sum_{\bfq \neq 0} v_\bfq  | n_0(\bfq) |^2 e^{i\bfq \cdot \bfR_n}.
L000307	    \ee
L000308	We now convert the sum on $\bfq$ to an integral, keeping in mind that we must also then add in the interaction with the neutralizing background. Evaluating the integral (and keeping the background term implicit) gives
L000309	    \be
L000310	    \langle \Psi | V | \Psi \rangle = \frac{N}{2}e^2 \sum_{\bfR_n \neq 0} \frac{\sqrt \pi}{2 \tilde\sigma} e^{-R_n^2/8\tilde\sigma^2}I_0\left(\frac{R_n^2}{8\tilde\sigma^2}\right),
L000311	    \label{eq:V_WC_I0}
L000312	    \ee
L000313	where $\tilde \sigma^2 = \sigma^2 (1+\Omega/4\sigma^2)^2$ and $I_n(x)$ is the modified Bessel function.
L000314	
L000315	For large $r_s$, the the localized orbitals will be sharply peaked around the lattice sites, $\sigma \ll a_\text{WC}$, and we may expand
L000316		\be
L000317		\frac{\sqrt \pi}{2\tilde \sigma} e^{-R_n^2/8\tilde \sigma^2} I_0\left(\frac{R_n^2}{8\tilde \sigma^2}\right) = \frac{1}{R_n} + \frac{\tilde\sigma^2}{R_n^3} + \ldots.
L000318		\ee
L000319	To the lowest order, we thus arrive at the result
L000320		\be
L000321		\langle  \Psi | V | \Psi \rangle = \frac N2 \sum_{\bfR_n \neq 0} \frac{e^2\tilde\sigma^2}{R_n^3}+ E_\text{cl}, \quad E_\text{cl} = \frac N2 \sum_{\bfR_n \neq 0} \frac{e^2}{R_n}.
L000322	    \label{eq:V_WC}
L000323		\ee
L000324	Here $E_\text{cl}$ is the classical Coulomb energy of the crystal, which implicitly includes the interaction with the neutralizing background \cite{bonsall1977}. The dipolar sum may be evaluated numerically: $\sum_{\bfR_n \neq 0} 1/R_n^3 = \gamma / a_\text{WC}^3$, where $\gamma \approx 11.03$.
L000325	
L000326	Combining the potential energy with the kinetic energy \eqref{eq:t_wc} we arrive at Eq.~(5) of the main text for the energy per electron of the monatomic WC. We note that this result for the energy of the WC in a band with quantum geometry has also been obtained in \cite{tan2025}.
L000327	
L000328	\subsection{Variational energy of the paired WC}
L000329	
L000330	We now turn to the paired WC and use the same shorthand as above $b^\dag(\bfR_n) \to b^\dag_n$. The expectation value of the kinetic energy is
L000331		\begin{align}
L000332		\langle \Psi_p | T | \Psi_p \rangle &= \frac {1}{2^{N_{p}}}\sum_{\bfk\sigma} \epsilon_\bfk \langle 0 | b_{N_p} \ldots  b_1 (c^\dag_{\bfk\sigma} c_{\bfk\sigma} ) b^\dag_1 \ldots b^\dag_{N_p} | 0\rangle \\
L000333		&=  \frac {1}{2^{N_{p}}}\sum_{\bfk\sigma} \epsilon_\bfk \langle 0 | b_{N_p} \ldots  b_2 (b_{1}  b^\dag_{1}) (c^\dag_{\bfk\sigma} c_{\bfk\sigma} ) b^\dag_2 \ldots b^\dag_{N_p} | 0\rangle  + \frac{1}{2^{N_{p}}} \sum_{\bfk\sigma} \epsilon_\bfk \langle 0 | b_{N_p} \ldots  b_{2} ( b_1 [c^\dag_{\bfk\sigma} c_{\bfk\sigma}, b^\dag_1] ) b^\dag_2 \ldots b^\dag_{N_p} | 0\rangle
L000334		\end{align}
L000335	Next, we write $b_1[c^\dag_{\bfk\sigma} c_{\bfk\sigma}, b^\dag_1]  = [b_1, [c^\dag_{\bfk\sigma} c_{\bfk\sigma}, b^\dag_1] ] +   [c^\dag_{\bfk\sigma} c_{\bfk\sigma}, b^\dag_1] b_1$ and use the (approximate) bosonic commutation relations \eqref{eq:b_comm} to move operator $b_1$ in the second term all the way to the right to annihilate the vacuum. Utilizing the nested commutator \eqref{eq:nested_comm}, we thus obtain
L000336	\begin{align}
L000337		\langle \Psi_p | T | \Psi_p \rangle &= \frac{1}{2^{N_p}} \sum_{\bfk\sigma} \epsilon_\bfk \langle 0 | b_{N_p}\ldots  b_2 (b_1  b^\dag_1) (c^\dag_{\bfk\sigma} c_{\bfk\sigma} ) b^\dag_2 \ldots b^\dag_{N_p} | 0\rangle  \nonumber \\
L000338		&\quad +  \frac{4}{A^2} \sum_{\bfk\bfk'} \epsilon_\bfk |\Phi(\bfk + \bfk')|^2 \left |\varphi\left(\frac{\bfk - \bfk'}{2}\right) \right|^2
L000339		\frac{1}{2^{N_p}}\underbrace{ \langle 0 |b_{N_p} \ldots  b_2 b^\dag_2 \ldots b^\dag_{N_p} | 0\rangle}_{\approx 2^{N_p-1}} .
L000340		\end{align}
L000341	Continuing to commute the operator $c^\dag_{\bfk\sigma} c_{\bfk\sigma}$ to the right gives $N_p$ similar terms, resulting in
L000342		\begin{align}
L000343		\langle \Psi_p | T | \Psi_p \rangle  &=  2 N_p \int \frac{\dd^2\bfk}{(2\pi)^2} ~ \frac{\dd^2\bfk'}{(2\pi)^2} \epsilon_{\bfk} |\Phi(\bfk + \bfk')|^2 \left |\varphi\left(\frac{\bfk - \bfk'}{2}\right) \right|^2   \\
L000344	    &= N_p  \int \frac{\dd^2\bfq}{(2\pi)^2} ~  \frac{\hbar^2\bfq^2}{2M} |\Phi(\bfq)|^2 + N_p \int \frac{\dd^2\bfk}{(2\pi)^2} ~  \frac{\hbar^2\bfk^2}{2\mu} |\varphi(\bfk)|^2,
L000345	    \label{eq:T_PWC}
L000346		\end{align}
L000347	where $M=2m^*$ and $\mu = m^*/2$. The kinetic energy thus factorizes into a sum of COM and relative contributions. Using the Gaussian form of the COM wave function, we have explicitly $T_\text{COM} = N_p \hbar^2 /4 M\sigma_p^2$.
L000348	
L000349	The calculation of the potential energy is more involved, but the basic manipulations are very similar to those made in calculating the kinetic energy. Here we just highlight the main steps. The expectation value is
L000350		\be
L000351		\langle \Psi_p | V | \Psi_p \rangle = \frac{1}{2A} \sum_{\bfq \neq 0} v_\bfq \sum_{\bfk\bfk'} F_{\bfk + \bfq,\bfk}F_{\bfk' - \bfq,\bfk'}  \frac{1}{2^{N_p}}\langle 0 | b_{N_p} \ldots  b_1 \mathcal O^{\bfq}_{\bfk\bfk'} b^\dag_{1} \ldots b^\dag_{N_p} | 0\rangle,
L000352		\ee
L000353	where $\mathcal O^{\bfq}_{\bfk \bfk'} \equiv c^\dag_{\bfk'-\bfq\sigma'}c^\dag_{\bfk+\bfq\sigma}c_{\bfk\sigma}c_{\bfk'\sigma'}$. As with the kinetic energy, we express this in terms of nested commutators:
L000354		\begin{align}
L000355	     \langle 0 | b_{N_p} \ldots  b_1 \mathcal O^{\bfq}_{\bfk\bfk'} b^\dag_1 \ldots  b^\dag_{N_p}| 0\rangle &=\sum_{n=1}^{N_p} \langle 0 | \left( \prod_{i<n} b_i b_i^\dag\right) \left( \prod_{i>n} b_i\right) \mathcal C^{\bfq}_{\bfk\bfk',n}\left( \prod_{i>n} b^\dag_i\right) | 0 \rangle,   \quad \mathcal C^{\bfq}_{\bfk\bfk',n} \equiv [b_n, \mathcal [\mathcal O^{\bfq}_{\bfk\bfk'}, b^\dag_n]].
L000356		 \label{eq:nested_V}
L000357		\end{align}
L000358	This result is obtained using the approximate relation \eqref{eq:b_comm}. The nested commutator $\mathcal C$ has the schematic structure
L000359		\be
L000360		\mathcal C^{\bfq}_{\bfk\bfk',n}  = A_n + \sum_{\alpha\beta}B_n^{\alpha\beta}c^\dag_\alpha c_\beta + \sum_{\alpha\beta\gamma\delta}D_n^{\alpha\beta\gamma\delta} c^\dag_\alpha c^\dag_\beta c_\gamma c_\delta.
L000361		 \label{eq:commutator_decomp}
L000362		\ee
L000363	Here $A_n$, $B_n$, and $D_n$ are $c$-numbers and their dependence on $\bfk$, $\bfk'$, and $\bfq$ has been left implicit. One can show that the four-fermion $D_n$ term gives contributions that vanish in the approximation of no intercell overlap. Direct calculation shows that the constant term $A_n$ is given by
L000364		\be
L000365		A_n = \frac{4}{A^2} |\tilde\Phi(\bfk + \bfk')|^2  \tilde\varphi^*\left(\frac{\bfk - \bfk'}{2} + \bfq \right) \tilde\varphi\left(\frac{\bfk - \bfk'}{2}\right)
L000366		\ee
L000367	and is independent of the site $\bfR_n$. There will be one such term for each pair, yielding the contribution
L000368		\be
L000369		\langle \Psi_p | V | \Psi_p \rangle \ni V_\text{intra}  = N_p \int \frac{\dd^2\bfq}{(2\pi)^2} ~ v_\bfq e^{-\Omega q^2/2} \int \frac{\dd^2\bfk}{(2\pi)^2}~ \tilde\varphi^*(\bfk + \bfq) \tilde\varphi(\bfk) e^{-i\Omega \bfq \times \bfk}.
L000370	    \label{eq:Vintra_PWC}
L000371		\ee
L000372	These terms corresponds to the \textit{intracell} Coulomb interaction energy of the pair.
L000373	
L000374	When the bilinear term in Eq.~\eqref{eq:commutator_decomp} is inserted into \eqref{eq:nested_V}, the result can, in the approximation of vanishing intercell overlaps, again be written as a sum of expectation values of the nested commutators
L000375	    \be
L000376	    C^{\bfq}_{\bfk\bfk',nm} \equiv [b_m, [\sum_{\alpha\beta} B_n^{\alpha\beta} c^\dag_\alpha c_\beta,b_m^\dag]].
L000377	    \ee
L000378	The contribution to the expectation value from the bilinear terms is then
L000379	    \begin{align}
L000380	    \langle 0 | b_{N_p} \ldots  b_1 \mathcal O^{\bfq}_{\bfk\bfk'} b^\dag_1 \ldots  b^\dag_{N_p}| 0\rangle_\text{bilinear} &= \sum_{n>m} \langle 0 | \left( \prod_{i<n} b_i b_i^\dag\right) \left( \prod_{n<i<m} b_i b_i^\dag\right) \left( \prod_{i>m} b_i\right) \mathcal C^{\bfq}_{\bfk\bfk',nm}\left( \prod_{i>m} b^\dag_i\right) | 0 \rangle \\
L000381	    &\approx 2^{N_p-2} \sum_{n > m} \langle 0 | C^{\bfq}_{\bfk\bfk',nm} | 0 \rangle ,
L000382	    \end{align}
L000383	the last line being valid in the no-overlap approximation.
L000384	Furthermore, direct calculation shows that only the following two types of bilinear terms survive in the no-overlap approximation:
L000385		\be
L000386		\begin{aligned}
L000387		 \sum_{\alpha\beta}B_n^{\alpha\beta}c^\dag_\alpha c_\beta &\to \frac{4}{A^2}\sum_{\bfk''} e^{i\bfq \cdot \bfR_n} \tilde\Phi^*(\bfk''+\bfq) \tilde\Phi(\bfk'') \tilde\varphi^*\left(\frac{\bfk'' - 2\bfk - \bfq}{2}\right) \tilde\varphi\left(\frac{\bfk'' - 2\bfk}{2}\right) c^\dag_{\bfk'-\bfq \sigma'} c_{\bfk'\sigma'} \\
L000388		 &\qquad +\frac{4}{A^2} \sum_{\bfk''} e^{-i\bfq \cdot \bfR_n} \tilde\Phi^*(\bfk'' - \bfq) \tilde\Phi(\bfk'') \tilde\varphi^*\left(\frac{\bfk'' - 2\bfk' + \bfq}{2}\right) \tilde\varphi\left(\frac{\bfk'' - 2\bfk'}{2}\right) c^\dag_{\bfk+\bfq \sigma} c_{\bfk\sigma}.
L000389		 \end{aligned}
L000390	    \label{eq:bilinears}
L000391	 	\ee
L000392	Here spinor sums $\sum_{\sigma_1\sigma_2}\chi^2_{\sigma_1\sigma_2} =1$ have been evaluated.
L000393	
L000394	Putting everything together, we arrive, after some algebraic manipulation, at the following contribution from the bilinear terms:
L000395		\be
L000396		\langle \Psi_p | V | \Psi_p \rangle \ni  V^0_\text{inter} = \frac{N_p}{2A}\sum_{\bfR_n \neq 0}  \sum_{\bfq\neq 0} ~ 4v_\bfq |\rho_0(\bfq)|^2    |\varrho_0(\bfq/2)|^2 e^{i\bfq\cdot \bfR_n}.
L000397	    \label{eq:v_inter}
L000398		\ee
L000399	We have defined, respectively, the COM and relative densities as
L000400	    \be
L000401	    \rho_0(\bfq) = \int \frac{\dd^2\bfk}{(2\pi)^2} ~ F^{(\Omega/2)}_{\bfk-\bfq, \bfk} \tilde \Phi^*(\bfk - \bfq) \tilde \Phi(\bfk), \quad \varrho_0(\bfq) = \int \frac{\dd^2\bfk}{(2\pi)^2} ~ F^{(2\Omega)}_{\bfk-\bfq, \bfk} \tilde \varphi^*(\bfk - \bfq) \tilde \varphi(\bfk),
L000402	    \ee
L000403	where the superscipt on the form factor $F$ indicates the replacements $\Omega \to \Omega/2$ and $\Omega \to 2\Omega$.
L000404	
L000405	The product of densities appearing in the sum \eqref{eq:v_inter} is simply related to the Fourier component of the \textit{total} density, $n(\bfq) = \langle \Psi_p | \sum_{\bfk \sigma} F_{\bfk-\bfq,\bfk}c^\dag_{\bfk-\bfq\sigma}c_{\bfk\sigma} | \Psi_p \rangle$: in the limit of vanishing intercell overlaps, we have
L000406	    \be
L000407	    n(\bfq) = \sum_n e^{-i\bfq \cdot \bfR_n} n_0(\bfq), \quad n_0(\bfq) = 2\rho_0(\bfq) \varrho_0(\bfq/2).
L000408	    \ee
L000409	The intercell potential energy term \eqref{eq:v_inter} is thus
L000410		\be
L000411		V^0_\text{inter} =  \frac{N_p}{2A}\sum_{\bfR_n \neq 0}  \sum_{\bfq \neq 0} v_\bfq |n_0(\bfq)|^2   e^{i\bfq\cdot \bfR_n}.
L000412	    \label{eq:v_inter2}
L000413		\ee
L000414	
L000415	In the final step, we make a small-$\bfq$ expansion of $\varrho_0(\bfq/2)$, which amounts to a multipole expansion of the charge distribution of the pair. After some algebra, we obtain
L000416	    \be
L000417	    \varrho_0(\bfq/2) = 1 - \frac{q^2}{16}\int \frac{\dd^2\bfk}{(2\pi)^2} ~ \varphi^*(\bfk)  \left[ \left(i\nabla_\bfk + 2 \mathcal A_\bfk\right)^2  + 2\Omega  \right] \varphi(\bfk) + \ldots
L000418	    \ee
L000419	Plugging this into \eqref{eq:v_inter}, we find
L000420	    \be
L000421	    V^0_\text{inter} = \frac{N_p}{2A}\sum_{\bfR_n \neq 0} \sum_{\bfq \neq 0} ~ v^{(2e)}_\bfq |\rho_0(\bfq)|^2 e^{i\bfq\cdot \bfR_n} + N_p  \int \frac{\dd^2\bfk}{(2\pi)^2} ~ \varphi^*(\bfk)  \left[ \frac K2\left(i\nabla_\bfk + 2 \mathcal A_\bfk\right)^2  + K\Omega \right] \varphi(\bfk)
L000422	    \label{eq:v_inter_expand}
L000423	    \ee
L000424	Here $v^{(2e)} \equiv 2\pi (2e)^2/q$ and the Berry connection is $\mathcal A_\bfk = {\boldsymbol\Omega} \times \bfk /2$.
L000425	In the first term, the internal structure of the pair drops out and we obtain the intercell Coulomb interaction between composite objects (the pairs) of charge $2e$; the result is the same as that obtained for the ordinary WC \eqref{eq:V_WC} with the substitutions $N \to N_p$, $a_\text{WC} \to a'_\text{WC} = \sqrt 2 a_\text{WC}$, $e \to 2e$, and $\Omega \to \Omega/2$.
L000426	The second term is an \textit{intracell} harmonic confining potential that arises as a result of \textit{intercell} interactions between the pair and the surrounding electrons. The stiffness $K$ of the harmonic potential is
L000427	    \be
L000428	    K = -\sum_{\bfR_n \neq 0} \frac{e^2}{2R^3}\int_0^\infty \dd x ~ x^2 e^{-\frac{\sigma_p^2}{R_n^2}\left(1 + \frac{\Omega}{8\sigma_p^2}\right)^2 x^2} J_0(x) \approx \sum_{\bfR_n \neq 0} \frac{e^2}{2R_n^3}=\frac{\gamma e^{2}}{2a^{\prime 3}_{\text{WC}}},
L000429	    \ee
L000430	where the last approximation is for the localized limit $\sigma_p \ll a_\text{WC}$.
L000431	
L000432	The COM contribution to the kinetic energy in Eq.~\eqref{eq:T_PWC}, together with the intercell interaction energy in Eq.~\eqref{eq:v_inter_expand}, gives the first three terms of the paired WC energy in Eq.~(9) of the main text. Adding the relative kinetic energy in Eq.~\eqref{eq:T_PWC} to the intracell Coulomb interaction in Eq.~\eqref{eq:Vintra_PWC} and the harmonic confining potential in Eq.~\eqref{eq:v_inter_expand} leads to the Schrödinger equation for the internal pair energy $\epsilon_{0m}$ and pair wave function $\varphi(\bfk)$ in Eq.~(11) of the main text.
L000433	
L000434	\section{Variational states and energies: wave function approach}
L000435	
L000436	In this section of the supplemental material, we demonstrate that a first-quantized approach based on Hartree-type wave functions reproduces the results of the preceding section obtained using second-quantization. The appeal of the first-quantized approach lies in the relative simplicity of the variational wave functions and in the calculation of the variational energies.
L000437	
L000438	We start with the first-quantized representation of the Hamiltonian:
L000439	\be
L000440	H=\sum_{i}\frac{\hbar^{2}\hat{\bfk}_{i}^{2}}{2m^{*}}+\frac{1}{2}\sum_{i\neq j}\hat{V}_{ij},
L000441	\ee
L000442	where the Coulomb operator has matrix elements
L000443	\be
L000444	\Bra{\bfk_{i}\bfk_{j}}\hat{V}_{ij}\Ket{\bfk_{i}^{\prime}\bfk_{j}^{\prime}}=\delta\left(\bfk_{i}+\bfk_{j}-\bfk_{i}^{\prime}-\bfk_{j}^{\prime}\right)v\left(\bfk_{i}-\bfk_{i}^{\prime}\right)F_{\bfk_{i},\bfk_{i}^{\prime}}F_{\bfk_{j},\bfk_{j}^{\prime}}
L000445	\ee
L000446	and the form factors are given in Eq.~\eqref{eq:form_factor}.
L000447	The real space matrix elements of the interaction are given by
L000448	\begin{align}
L000449	\Bra{\bfr_{1},\bfr_{2}}\hat{V}\Ket{\bfr_{1}^{\prime},\bfr_{2}^{\prime}}&=\int \frac{\dd^2\bfq}{(2\pi)^2}v_\bfq e^{-\frac{\Omega}{2}q^{2}}e^{i\bfq\cdot\left(\bfr_{1}^{\prime}-\bfr_{2}^{\prime}\right)}\delta\left(\bfr_{1}+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}-\bfr_{1}^{\prime}\right)\delta\left(\bfr_{2}-\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}-\bfr_{2}^{\prime}\right)\label{eq:Vrrp}\\
L000450	 &= \frac{2e^2}{\pi\Omega\left|\bfr-\bfr^{\prime}\right|}e^{-(\bfr - \bfr')^2/2\Omega}e^{-i\bfr \times \bfr'/\Omega}\delta\left(\bfR-\bfR^{\prime}\right),
L000451	\end{align}
L000452	and we introduced the COM and relative coordinates $\bfr_{1,2}=\bfR\pm\bfr/2$ and $\bfr'_{1,2} = \bfR' \pm \bfr'/2$.
L000453	
L000454	For the monatomic WC, we consider an $N$-electron variational wave function in the Hartree approximation:
L000455	    \be
L000456	    \Psi(\bfr_1, \bfr_2, \ldots, \bfr_N) = \prod_{n=1}^N \Phi(\bfr_n - \bfR_n),
L000457	    \label{eq:wc_wave_func}
L000458	    \ee
L000459	where $\Phi(\bfr) = e^{-r^2/4\sigma^2}/\sqrt{2\pi \sigma^2}$. Here each electron $n$ has been identified with a WC lattice site $\bfR_n$. We are making the approximation of distinguishable electrons, which is good up to exponentially small corrections due to exchange processes in the WC.
L000460	
L000461	For the paired WC, we consider the wave function
L000462	    \be
L000463	    \Psi_p(\bfr_1, \bfr_2, \ldots, \bfr_N) = \prod_{n=1}^{N_p} \Phi\left(\frac{\bfr_{na}+\bfr_{nb}}{2} - \bfR_n\right)\varphi(\bfr_{na}-\bfr_{nb}).
L000464	    \label{eq:pwc_wave_func}
L000465	    \ee
L000466	Here $\bfr_{na}$ and $\bfr_{nb}$ are the coordinates of the two paired electrons localized near WC lattice site $\bfR_n$, and $\Phi$ and $\varphi$ are the COM and relative wave functions of a pair, respectively. For the COM wave function we take a Gaussian with a variational width $\sigma_p$, while the relative wave function is determined by solving the two-electron pairing problem in a WC unit cell. In this approximation we include exchange effects within a pair (the spatial pair wave function should be fully antisymmetrized together the spin part of the wave function), but neglect exchange between pairs.
L000467	
L000468	As we demonstrate explicitly below, using the Hartree-type wave functions \eqref{eq:wc_wave_func} and \eqref{eq:pwc_wave_func} yields  results identical to those of the second-quantized approach in the no-intercell-overlap approximation presented in the previous section. More comprehensive recent discussions of first-quantized wave functions in bands with nontrivial quantum geometry can be found in e.g., Refs.~\cite{tan2025,tan2025ideal}.
L000469	
L000470	\subsection{Variational energy of the monatomic WC}
L000471	
L000472	Using the wave function \eqref{eq:wc_wave_func}, the kinetic energy is readily found to to be  $\langle \Psi |  T  | \Psi \rangle = N \hbar ^2 / 4m^{*}\sigma^{2}$, in agreement with Eq.~\eqref{eq:t_wc}. The potential energy is
L000473	\begin{align}
L000474	    &\left \langle \Psi |  V | \Psi \right\rangle =\frac{N}{2}\sum_{\bfR_n\neq0}\int \dd^2\bfr_{1} \dd^2 \bfr_{2}\dd^2\bfr'_{1} \dd^2 \bfr'_{2}  ~ \Phi^{*}\left(\bfr_{1}\right)\Phi^{*}\left(\bfr_{2}-\bfR_n\right)\Phi\left(\bfr_{1}^{\prime}\right)\Phi\left(\bfr_{2}^{\prime}-\bfR_n\right)\Bra{\bfr_{1},\bfr_{2}}\hat{V}\Ket{\bfr_{1}^{\prime},\bfr_{2}^{\prime}}.
L000475	\end{align}
L000476	Plugging in the interaction matrix elements \eqref{eq:Vrrp} and integrating over the primed coordinates gives
L000477	    \be
L000478	    \begin{aligned}
L000479	    \left \langle \Psi |  V | \Psi \right\rangle  &= \frac{N}{2A}\sum_{\bfR_n\neq0} \sum_{\bfq \neq 0} v_\bfq e^{-\frac{\Omega}{2}q^{2}}e^{-i\bfq\cdot\bfR_n} \\
L000480	    &\qquad \times \int \dd^2\bfr_{1} \dd^2 \bfr_{2}  ~\Phi^{*}\left(\bfr_{1}\right)\Phi^{*}\left(\bfr_{2}\right)\Phi\left(\bfr_{1}+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right)\Phi\left(\bfr_{2}-\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right)e^{i\bfq\cdot\left(\bfr_{1}-\bfr_{2}\right)}.
L000481	    \end{aligned}
L000482	    \ee
L000483	The integrals can be directly computed using the Gaussian form of the variational wave function, giving
L000484	\begin{align}
L000485	I_\pm\left(\bfq,\Omega\right)=\int \dd^2\bfr ~ e^{\pm i\bfq\cdot\bfr}\Phi^{*}\left(\bfr\right)\Phi\left(\bfr\pm\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right)=\exp\left\{ -\frac{q^{2}\sigma^{2}}{2}\left(1+\frac{\Omega^{2}}{16\sigma^{4}}\right)\right\}.
L000486	\end{align}
L000487	This gives the potential energy
L000488	\begin{align}
L000489	    &\left \langle \Psi |  V | \Psi \right\rangle =\frac{N}{2}\sum_{\bfR_n\neq0}\int \frac{\dd^2\bfq}{(2\pi)^2} ~ v_\bfq e^{-\tilde{\sigma}^{2}q^{2}}e^{-i\bfq\cdot\bfR_n}=\frac{Ne^{2}}{2}\sum_{\bfR_n\neq0}\frac{\sqrt{\pi}}{2\tilde{\sigma}}e^{ -\frac{R^2_{n}}{8\tilde{\sigma}^{2}}}I_{0}\left(\frac{R^{2}_n}{8\tilde{\sigma}^{2}}\right),
L000490	\end{align}
L000491	in agreement with Eq.~\eqref{eq:V_WC_I0} obtained using the second-quantized approach.
L000492	
L000493	\subsection{Variational energy of the paired WC}
L000494	
L000495	Taking the pair state wavefunction ansatz \eqref{eq:pwc_wave_func}, we proceed to the calculation of the paired crystal energy. The kinetic energy factorizes as a sum of the kinetic energies of the COM and relative coordinates of the pairs.
L000496	\be
L000497	    \langle \Psi_p | T | \Psi_p \rangle = N_{p}\frac{\hbar^{2}}{4M\sigma^{2}_{p}}+N_p \int \dd^{2}\bfr  ~ \varphi^{*}\left(\bfr\right)\frac{\hat{\bfp}^{2}}{2\mu}\varphi\left(\bfr\right),
L000498	\ee
L000499	in agreement with Eq.~\eqref{eq:T_PWC}.
L000500	
L000501	The calculation of potential energy here is more involved and must account for both the intra- and intercell Coulomb interactions. We write it as
L000502	\begin{align}
L000503	    & \langle \Psi_p |  V | \Psi_p \rangle = N_{p}v_{\text{intra}}+\frac{N_{p}}{2}v_{\text{inter}}.
L000504	\end{align}
L000505	
L000506	
L000507	\subsubsection{Intracell interaction}
L000508	
L000509	For the intracell interaction, we have the expression
L000510	\begin{align}
L000511	    &v_{\text{intra}}=\int \dd^2\bfr_{1} \dd^2 \bfr_{2}\dd^2\bfr'_{1} \dd^2 \bfr'_{2} ~ \psi^{*}\left(\bfr_{1},\bfr_{2}\right)\psi\left(\bfr_{1}^{\prime},\bfr_{2}^{\prime}\right)\Bra{\bfr_{1},\bfr_{2}}\hat{V}\Ket{\bfr_{1}^{\prime},\bfr_{2}^{\prime}},
L000512	\end{align}
L000513	where $\psi(\bfr_1,\bfr_2) = \Phi\left( (\bfr_1 + \bfr_2)/2\right) \varphi(\bfr_1 - \bfr_2)$.
L000514	Using the matrix elements \eqref{eq:Vrrp} and performing the integrals over primed coordinates, we obtain
L000515	\begin{align} v_{\text{intra}} &=\int \frac{\dd^2\bfq}{(2\pi)^2} ~ v_\bfq e^{-\frac{\Omega}{2}q^{2}}\int \dd^2\bfr_{1} \dd^2 \bfr_{2} ~ \psi^{*}\left(\bfr_{1},\bfr_{2}\right)\psi\left(\bfr_{1}+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2},\bfr_{2}-\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right)e^{i\bfq\cdot\left(\bfr_{1}-\bfr_{2}\right)},\\
L000516	&=\int \frac{\dd^2\bfq}{(2\pi)^2} ~ v_\bfq e^{-\frac{\Omega}{2}q^{2}}\int \dd^2\bfr ~  \varphi^{*}\left(\bfr\right)\varphi\left(\bfr+\left(\bfq\times\boldsymbol{\Omega}\right)\right)e^{i\bfq\cdot\bfr}.
L000517	\end{align}
L000518	Fourier transforming $\varphi(\bfr) \to \tilde\varphi(\bfk)$ gives the intracell interaction energy in Eq.~\eqref{eq:Vintra_PWC}.
L000519	
L000520	\subsubsection{Intercell interaction}
L000521	
L000522	Now we compute the potential energy of the Coulomb interaction between pairs of electrons. Denote the particles in one unit cell by $1$ and $2$ and the particles in another unit cell by $1^{\prime}$ and $2^{\prime}$. Then the contribution to the potential energy coming from the interaction between the cells is given by
L000523	\begin{align}
L000524	v_{\text{inter}}&=v_{11^{\prime}}+v_{12^{\prime}}+v_{21^{\prime}}+v_{22^{\prime}} \\
L000525	&=\sum_{\bfR_n\neq0}\int_{\left\{ \bfr_{i}\right\} ,\left\{ \bfb_{i}\right\} }\psi^{*}\left(\bfr_{1},\bfr_{2}\right)\psi^{*}\left(\bfr_{1}^{\prime}-\bfR_n,\bfr_{2}^{\prime}-\bfR_n\right)\psi\left(\bfb_{1},\bfb_{2}\right)\psi\left(\bfb_{1}^{\prime}-\bfR_n,\bfb_{2}^{\prime}-\bfR_n\right) \nonumber \\
L000526	    &\qquad \times\left( \Bra{\bfr_{1}\bfr_{1}^{\prime}\bfr_{2}\bfr_{2}^{\prime}}\hat{V}_{11^{\prime}}\Ket{\bfb_{1}\bfb_{1}^{\prime}\bfb_{2}\bfb_{2}^{\prime}}+\Bra{\bfr_{1}\bfr_{2}^{\prime}\bfr_{2}\bfr_{1}^{\prime}}\hat{V}_{12^{\prime}}\Ket{\bfb_{1}\bfb_{2}^{\prime}\bfb_{2}\bfb_{1}^{\prime}} \right. \nonumber \\
L000527	    &\qquad ~~~~~  \left. +\Bra{\bfr_{2}\bfr_{1}^{\prime}\bfr_{1}\bfr_{2}^{\prime}}\hat{V}_{21^{\prime}}\Ket{\bfb_{2}\bfb_{1}^{\prime}\bfb_{1}\bfb_{2}^{\prime}}+\Bra{\bfr_{2}\bfr_{2}^{\prime}\bfr_{1}\bfr_{1}^{\prime}}\hat{V}_{22^{\prime}}\Ket{\bfb_{2}\bfb_{2}^{\prime}\bfb_{1}\bfb_{1}^{\prime}}\right) ,
L000528	\end{align}
L000529	where $\left\{ \bfr_{i}\right\}=\{\bfr_{1},\bfr_{2},\bfr_{1}^{\prime},\bfr_{2}^{\prime}\}$ and $\left\{ \bfb_{i}\right\} = \{\bfb_{1},\bfb_{2},\bfb_{1}^{\prime},\bfb_{2}^{\prime}\}$.
L000530	Using the fact that the electrons in a pair are indistinguishable, we recognize that all four terms in the sum above are equal. We thus focus on one representative, for example, $v_{12^\prime}$, such that
L000531	$v_{\text{inter}}=4v_{12^\prime}$.
L000532	
L000533	The four-body matrix element of the interaction for this term has the form
L000534	\begin{equation}
L000535	\begin{aligned}
L000536	&\Bra{\bfr_{1}\bfr_{2}^{\prime}\bfr_{2}\bfr_{1}^{\prime}}\hat{V}_{12^{\prime}}\Ket{\bfb_{1}\bfb_{2}^{\prime}\bfb_{2}\bfb_{1}^{\prime}}=\Bra{\bfr_{1}\bfr_{2}^{\prime}}\hat{V}_{12^{\prime}}\Ket{\bfb_{1}\bfb_{2}^{\prime}}\delta\left(\bfr_{2}-\bfb_{2}\right)\delta\left(\bfr_{1}^{\prime}-\bfb_{1}^{\prime}\right).
L000537	\end{aligned}
L000538	\end{equation}
L000539	Putting in the matrix elements \eqref{eq:Vrrp} and performing the integrals using the delta functions, we arrive at
L000540	\begin{equation}
L000541	\begin{aligned}
L000542	v_\text{inter} &= \frac{1}{A}\sum_{\bfR_{n}\neq0}\sum_{\bfq \neq 0}  4v_\bfq e^{-\frac{\Omega}{2}q^{2}}e^{-i\bfq\cdot\bfR_{n}}\\
L000543	&\qquad \times\int \dd^2\bfR \dd^2\bfR^{\prime} ~ e^{i\bfq\cdot\left(\bfR-\bfR^{\prime}\right)}\Phi^{*}\left(\bfR\right)\Phi^{*}\left(\bfR^{\prime}\right)\Phi\left(\bfR+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{4}\right)\Phi\left(\bfR^{\prime}-\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{4}\right) \\
L000544	&\qquad \times \int \dd^2\bfr \dd^2\bfr^{\prime} ~ e^{i\bfq\cdot\frac{\bfr+\bfr^{\prime}}{2}}\varphi^{*}\left(\bfr\right)\varphi^{*}\left(\bfr^{\prime}\right)\varphi\left(\bfr+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right)\varphi\left(\bfr^{\prime}+\frac{\left(\bfq\times\boldsymbol{\Omega}\right)}{2}\right).
L000545	\end{aligned}
L000546	\end{equation}
L000547	Fourier transforming $\Phi(\bfr) \to \tilde\Phi(\bfq)$ and $\varphi(\bfr) \to \tilde\varphi(\bfk)$ we recover precisely the result \eqref{eq:v_inter} obtained in the second-quantization approach.
L000548	
L000549	\section{Quantum mechanics in a topological band}
L000550	
L000551	In this section, we briefly summarize the algorithm to obtain the first-quantized, wave function description of a particle in a band with nontrivial quantum geometry determined by the form factor \eqref{eq:form_factor}.
L000552	
L000553	To account for both the Berry curvature and quantum metric of the band, one needs to perform the real-space analog of the Peierls substitution in the potential
L000554	\be
L000555	    \hat\bfr\to \hat\bfr+\hat{\mathcal{A}}_{\bfk}
L000556	\ee
L000557	and dress the potential with the quantum metric factor
L000558	\begin{align}
L000559	    &v\left(\bfr\right)=\int\frac{\dd^{2}\bfq}{(2\pi)^2} {\left(2\pi\right)^{2}} ~ v_\bfq e^{i\bfq\cdot\bfr}\to v_{\Omega}\left(\bfr\right)=\int\frac{\dd^{2}\bfq}{\left(2\pi\right)^{2}} ~ v_\bfq e^{-\frac{\Omega}{4}q^{2}}e^{i\bfq\cdot\bfr}.
L000560	\end{align}
L000561	
L000562	As an example, consider the Coulomb potential in 2D, $v_\bfq = 2\pi e^2/q$. A straightforward calculation gives
L000563	\be
L000564	    v\left(\bfr\right)=\frac{e^{2}}{r}\to v_{\Omega}\left(\bfr\right)=e^{2}\int_{0}^{\infty} \dd q  ~ J_{0}\left(qr\right)e^{-\frac{\Omega}{4}q^{2}}=e^{2}\sqrt{\frac{\pi}{\Omega}} e^{-\frac{r^{2}}{2\Omega}}  I_{0}\left(\frac{r^{2}}{2\Omega}\right).
L000565	\ee
L000566	For $r \gg \sqrt \Omega$, $v_\Omega$ tends to the usual Coulomb. However, at short distances $r \ll \sqrt\Omega$, the effective ``size" of the particle induced by quantum geometry cuts off the divergence in the Coulomb potential.
L000567	
L000568	For the harmonic potential, the action of the derivative on the exponential factor $\exp(-\Omega q^2/4)$ produces a shift
L000569	\begin{align}
L000570	    & v_{\text{harm}}\left(\bfr\right)=\frac{K\bfr^{2}}{2}\to v^{\Omega}_{\text{harm}}\left(\bfr\right)=\frac{K\bfr^{2}}{2}+\frac{K\Omega}{2}.
L000571	\end{align}
L000572	
L000573	The single-particle behavior in a band with dispersion $\epsilon\left(\bfk\right)$ and uniform Berry curvature $\Omega$ with form factors \eqref{eq:form_factor} subjected to a potential $V(\bfr)$ is thus governed by the Hamiltonian
L000574	\begin{align}
L000575	    & \hat{H}_{\Omega}= \epsilon(\hat{\bfk})+V_{\Omega}(\hat{\bfr}+\hat{\mathcal{A}}_\bfk).
L000576	\end{align}
L000577	
